<?php

namespace PandoraBundle\Repository;

use Doctrine\ORM\EntityRepository;

/**
 * LanguageRepository
 *
 * This class was generated by the Doctrine ORM. Add your own custom
 * repository methods below.
 */
class LanguageRepository extends EntityRepository
{
    public function findUniqueViolation(array $parameter){
        $origParameter = $parameter;
        
        if($parameter['Id'] == 0){
            unset($parameter['Id']);
        }
        $result = $this->findBy($parameter);
        
        if($origParameter['Id'] > 0 && count($result) > 0){
            return [];
        }else{
            return $result;
        }
    }
}
